/// A munger which XORs a key with some data
#[derive(Clone)]
pub struct Xorcism<'a> {
    key: &'a [u8],
    pos: usize,
}

impl<'a> Xorcism<'a> {
    /// Create a new Xorcism munger from a key
    ///
    /// Should accept anything which has a cheap conversion to a byte slice.
    pub fn new<Key: AsRef<[u8]> + ?Sized>(key: &'a Key) -> Xorcism<'a> {
        Xorcism {
            key: key.as_ref(),
            pos: 0,
        }
    }

    /// Produce the next byte of the key, advancing internal state.
    fn next_key_byte(&mut self) -> u8 {
        let byte = self.key[self.pos];
        self.pos = (self.pos + 1) % self.key.len();
        byte
    }

    /// XOR each byte of the input buffer with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    pub fn munge_in_place(&mut self, data: &mut [u8]) {
        for byte in data.iter_mut() {
            *byte ^= self.next_key_byte();
        }
    }

    /// XOR each byte of the data with a byte from the key.
    ///
    /// Note that this is stateful: repeated calls are likely to produce different results,
    /// even with identical inputs.
    ///
    /// Should accept anything which has a cheap conversion to a byte iterator.
    /// Shouldn't matter whether the byte iterator's values are owned or borrowed.
    pub fn munge<Data>(&mut self, data: Data) -> impl Iterator<Item = u8> + 'a
    where
        Data: IntoIterator,
        Data::Item: std::borrow::Borrow<u8>,
        Data::IntoIter: 'a,
    {
        let mut this = self.clone();
        data.into_iter()
            .map(move |b| *b.borrow() ^ this.next_key_byte())
    }

    /// Wrap a `Read` implementation, XORing bytes as they are read.
    pub fn reader<R: Read>(self, reader: R) -> impl Read {
        XorReader { xs: self, reader }
    }

    /// Wrap a `Write` implementation, XORing bytes before they are written.
    pub fn writer<W: Write>(self, writer: W) -> impl Write {
        XorWriter { xs: self, writer }
    }
}

struct XorReader<'a, R> {
    xs: Xorcism<'a>,
    reader: R,
}

impl<'a, R: Read> Read for XorReader<'a, R> {
    fn read(&mut self, buf: &mut [u8]) -> IoResult<usize> {
        let bytes_read = self.reader.read(buf)?;
        self.xs.munge_in_place(&mut buf[..bytes_read]);
        Ok(bytes_read)
    }
}

struct XorWriter<'a, W> {
    xs: Xorcism<'a>,
    writer: W,
}

impl<'a, W: Write> Write for XorWriter<'a, W> {
    fn write(&mut self, buf: &[u8]) -> IoResult<usize> {
        let mut munged = buf.to_vec();
        self.xs.munge_in_place(&mut munged);
        self.writer.write(&munged)
    }

    fn flush(&mut self) -> IoResult<()> {
        self.writer.flush()
    }
}
"}

